import'dart:math' as math;import'package:flutter/material.dart';import'package:vector_math/vector_math_64.dart' hide Colors;
class Science3DViewport extends StatefulWidget{const Science3DViewport({super.key});@override State<Science3DViewport>createState()=>_Science3DViewportState();}
class _Science3DViewportState extends State<Science3DViewport>{double yaw=.4,pitch=.25,zoom=1;@override Widget build(BuildContext c)=>GestureDetector(onScaleUpdate:(d)=>setState((){yaw+=d.focalPointDelta.dx*.008;pitch=(pitch+d.focalPointDelta.dy*.008).clamp(-1.2,1.2);zoom=(zoom*d.scale).clamp(.5,3);}),child:CustomPaint(size:const Size(double.infinity,340),painter:_ScenePainter(yaw,pitch,zoom)));}
class _ScenePainter extends CustomPainter{final double yaw,pitch,zoom;_ScenePainter(this.yaw,this.pitch,this.zoom);Offset project(Vector3 v,Size s){final cy=math.cos(yaw),sy=math.sin(yaw),cp=math.cos(pitch),sp=math.sin(pitch);final x=cy*v.x+sy*v.z,z=-sy*v.x+cy*v.z,y=cp*v.y-sp*z,z2=sp*v.y+cp*z+4;final f=150*zoom/z2;return Offset(s.width/2+x*f,s.height/2-y*f);} @override void paint(Canvas c,Size s){c.drawRect(Offset.zero&s,Paint()..color=const Color(0xff07131f));final axis=Paint()..strokeWidth=2;for(final pair in [[Vector3.zero(),Vector3(1.5,0,0),Colors.red],[Vector3.zero(),Vector3(0,1.5,0),Colors.green],[Vector3.zero(),Vector3(0,0,1.5),Colors.blue]]){axis.color=pair[2]as Color;c.drawLine(project(pair[0]as Vector3,s),project(pair[1]as Vector3,s),axis);}final pts=[Vector3(-.8,-.5,-.5),Vector3(.8,-.5,-.5),Vector3(.8,.5,-.5),Vector3(-.8,.5,-.5),Vector3(-.8,-.5,.5),Vector3(.8,-.5,.5),Vector3(.8,.5,.5),Vector3(-.8,.5,.5)];final edges=[[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]],p=Paint()..color=Colors.tealAccent..strokeWidth=2;for(final e in edges)c.drawLine(project(pts[e[0]],s),project(pts[e[1]],s),p);}@override bool shouldRepaint(covariant _ScenePainter o)=>o.yaw!=yaw||o.pitch!=pitch||o.zoom!=zoom;}